<template><div><Form inline class="query" @submit.native.prevent="search"><FormItem v-if="searchable" label="订单 / 店铺 / 商品"><Input v-model="q" maxlength="80" clearable placeholder="输入搜索内容" @on-enter="search"/></FormItem><FormItem v-if="states.length" label="业务状态"><Select v-model="state" clearable style="min-width:180px"><Option v-for="v in states" :value="v" :key="v">{{label(v)}}</Option></Select></FormItem><FormItem v-if="dated" label="创建日期（北京）"><DatePicker v-model="dates" type="daterange" style="width:240px" placeholder="开始和结束日期"/></FormItem><Button type="primary" :loading="loading" @click="search">查询</Button><Button :disabled="loading" @click="reset">重置</Button><slot name="actions"/></Form><Alert v-if="error" type="error" show-icon>{{error}} <Button type="text" @click="load">重新读取</Button></Alert><div class="table-scroll"><Table :columns="tableColumns" :data="rows" :loading="loading" :no-data-text="q||state?'没有符合当前筛选的记录':'当前没有记录'"/></div><Page :current="page" :total="total" :page-size="20" show-total @on-change="turn"/></div></template>
<script>
import {s45Read} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';import {label,restoreDates,day} from '../presentation.cjs';
export default{props:{endpoint:String,columns:Array,states:{type:Array,default:()=>[]},params:{type:Object,default:()=>({})},searchable:{type:Boolean,default:true},dated:{type:Boolean,default:true},refreshKey:Number},data(){const q=this.$route.query;return{q:q.q||'',state:q.state||'',dates:restoreDates(q),page:Number(q.page)||1,rows:[],total:0,loading:false,error:'',ticket:0}},computed:{tableColumns(){return [...this.columns,{title:'操作',width:115,render:(h,{row})=>h('Button',{props:{size:'small'},on:{click:()=>this.$emit('open',row)}},'查看详情')}] }},watch:{refreshKey(){this.load()},endpoint(){this.page=1;this.load()}},mounted(){this.load()},beforeDestroy(){this.ticket++;this.rows=[]},methods:{label,async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const query={...this.params,pageNumber:this.page,pageSize:20,q:this.q,state:this.state};for(let i=0;i<2;i++){let d=day(this.dates[i]);if(d){let at=new Date(d+'T00:00:00+08:00');if(i)at=new Date(at.getTime()+86400000);query[i?'to':'from']=at.toISOString()}}const result=await s45Read(this.endpoint,query);if(ticket===this.ticket&&managerSession.sameSession(owner)){this.rows=result.records;this.total=result.total}}catch(e){if(ticket===this.ticket){this.rows=[];this.total=0;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}},remember(){const query={page:String(this.page)};if(this.q)query.q=this.q;if(this.state)query.state=this.state;for(let i=0;i<2;i++)if(day(this.dates[i]))query[i?'toDay':'fromDay']=day(this.dates[i]);this.$router.replace({path:this.$route.path,query}).catch(()=>{})},search(){this.page=1;this.remember();this.load()},reset(){this.q='';this.state='';this.dates=[];this.search()},turn(p){this.page=p;this.remember();this.load()}}};
</script>
